/// ReadOut 实例包装（@ohos 命名空间内嵌套接口）。
/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class ReadOut : JsObject
{
    public ReadOut(IntPtr handle) : base(handle) { }
    private static ReadOnlySpan<byte> _bytesRead => "bytesRead"u8;
    private static ReadOnlySpan<byte> _offset => "offset"u8;
    private static ReadOnlySpan<byte> _buffer => "buffer"u8;
    /// <summary>
    /// bytesRead
    /// </summary>
    public double BytesRead => NativeValue.ToDouble(GetPropertyRaw(_bytesRead));

    /// <summary>
    /// offset
    /// </summary>
    public double Offset => NativeValue.ToDouble(GetPropertyRaw(_offset));

    /// <summary>
    /// buffer
    /// </summary>
    public byte[] Buffer => ValueConverter.ConvertArray(GetPropertyRaw(_buffer), static e => ValueConverter.Convert<byte>(e));

}
